ee:variables.ee:set-variable:
%dw 2.0
output application/json
var filters = payload.filters
fun setQuery(op,value) = if (op == "eq") value else {"\$in": value}
---
filters map ((item, index) -> 
{
(item.field): setQuery(item.operator default "eq",item.value)
}
) reduce ((item, accumulator={}) -> accumulator ++ item)

ee:message.ee:set-payload:
%dw 2.0 output application/json fun setId(index) = payload."_id"."\$oid"[index] --- payload map ((item, index) ->
item - "_id" ++ {"id": setId(index)}
)
